// N3 - Critical Rule Checker (Phase 1)
// Deterministic checks — zero LLM cost

const item = $input.first().json;
const content = (item.content || '').trim();
const contentType = (item.content_type || 'email').toLowerCase();

const violations = [];
const passed = [];

const words = content.split(/\s+/).filter(Boolean);
const wordCount = words.length;

// Check 1 — Word Count
if (wordCount >= 10) {
  passed.push('word_count_ok');
} else {
  violations.push('content_too_short');
}

// Check 2 — Greeting
if (/^(hello|hi|dear)/i.test(content)) {
  passed.push('greeting_present');
} else {
  violations.push('missing_greeting');
}

// Check 3 — Prohibited Words
const prohibited = [
  'free money',
  'guaranteed',
  'urgent',
  'click here'
];

const found = prohibited.filter(word =>
  content.toLowerCase().includes(word)
);

if (found.length === 0) {
  passed.push('no_prohibited_words');
} else {
  violations.push('prohibited_words_found: ' + found.join(', '));
}

// Rule Score
const rule_score = Math.max(0, 100 - (violations.length * 25));

return [{
  json: {
    ...item,
    word_count: wordCount,
    rule_score,
    rule_violations: violations,
    rules_passed: passed,
    critical_violation: violations.length > 0
  }
}];

