// N6 - Confidence Score Engine
// Merges Phase 1 rule score + Phase 2 LLM score

const llmResponse = $input.first().json;
const ruleData = $('Rule Checker').first().json;

let quality_score = 50;
let reasoning = 'LLM review completed';
let tone_ok = true;
let clarity_ok = true;
let brand_aligned = true;
let parse_error = null;

// Parse Groq response safely
try {
  const raw = llmResponse?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw
    .replace(/```json/gi, '')
    .replace(/```/gi, '')
    .trim();
  const parsed = JSON.parse(cleaned);
  quality_score = Number(parsed.quality_score) || 50;
  reasoning = String(parsed.reasoning || 'No reasoning provided');
  tone_ok = parsed.tone_ok !== undefined ? Boolean(parsed.tone_ok) : true;
  clarity_ok = parsed.clarity_ok !== undefined ? Boolean(parsed.clarity_ok) : true;
  brand_aligned = parsed.brand_aligned !== undefined ? Boolean(parsed.brand_aligned) : true;
} catch (error) {
  parse_error = error.message;
  quality_score = 50;
  reasoning = 'Failed to parse LLM response. Default score applied.';
}

// Phase 1 Score
const rule_score = Number(ruleData.rule_score || 0);

// Final Weighted Score: Rule 40% + Quality 60%
const final_score = Math.round((rule_score * 0.4) + (quality_score * 0.6));

// Decision Engine
let decision = 'AUTO_REJECT';
if (final_score >= 85) decision = 'AUTO_SEND';
else if (final_score >= 60) decision = 'HUMAN_REVIEW';

// Human-friendly status
const review_status =
  decision === 'AUTO_SEND' ? 'APPROVED' :
  decision === 'HUMAN_REVIEW' ? 'PENDING_REVIEW' : 'REJECTED';

return [{
  json: {
    review_id: ruleData.review_id,
    received_at: ruleData.received_at,
    content: ruleData.content,
    content_type: ruleData.content_type,
    rules_profile: ruleData.rules_profile,
    destination: ruleData.destination,
    requester_email: ruleData.requester_email,
    word_count: ruleData.word_count,
    rule_score,
    rule_violations: ruleData.rule_violations || [],
    rules_passed: ruleData.rules_passed || [],
    quality_score,
    reasoning,
    tone_ok,
    clarity_ok,
    brand_aligned,
    final_score,
    decision,
    review_status,
    parse_error
  }
}];

